"""Test block EmptyState (Data): What a list, page or panel shows when it has nothing in it: why it's empty and the one thing to do next.

Generated by tools/blocks_from_app_blocks.py from the App Block card kit/blocks/data/EmptyState.md and its markup
(kit/blocks/data/EmptyState.html; source 45e808610602), with the vocabulary in
functional/blocks/spec.json. Do not edit: change the spec (or the App Block) and generate again.

Steps (e2e):
  Then I see the empty state {title}
  Then I see no empty state
  Then the empty state offers {name}
  When I take the empty state action {name}
  Then the empty state is in the {state} state
States (from the card): First run, No match, All done, No permission to create, Inside a small panel, Loading,
Search with no match. Checked by the state step: First run, All done.
"""
from __future__ import annotations

from functional import Registry
from functional import primitives as p

BLOCK = "EmptyState"
ROUTE = ""
STATES = ["First run", "No match", "All done", "No permission to create", "Inside a small panel", "Loading", "Search with no match"]
DEFAULT_STATE = "First run"
CHECKED_STATES = ["First run", "All done"]
DEMO = ["kit/blocks/data/EmptyState.html"]
SELF_TEST = [
    "Then I see the empty state \"No notes yet\"",
    "Then the empty state offers \"New Note\"",
    "Then the empty state offers \"Import from a File\"",
    "Then the empty state is in the \"First run\" state",
    "When I take the empty state action \"New Note\"",
    "Then I see the empty state \"No notes yet\"",
]

steps = Registry(block=BLOCK)


class EmptyState:
    """The EmptyState block on a page: its controls, found as a person finds them (role and name, label, text)."""

    def __init__(self, page, base_url: str = ""):
        self.page = page
        self.base_url = base_url

    def box(self):
        return p.control(self.page, css=".empty", block=BLOCK)

    def box_all(self):
        """Every match, possibly none (for counting)."""
        return self.page.locator(".empty")

    def heading(self):
        return p.control(self.box(), role="heading", block=BLOCK)

    def action(self, name):
        return p.control(self.box(), text=str(name), block=BLOCK)

    def actions(self):
        return p.control(self.box(), css="footer a, footer button", block=BLOCK)

    def actions_all(self):
        """Every match, possibly none (for counting)."""
        return self.box().locator("footer a, footer button")

    def expect_state(self, state: str) -> None:
        """Check one of the card's states: First run, All done."""
        b = self
        if state == "First run":
            p.expect_visible(b.actions().first)
        elif state == "All done":
            p.expect_count(b.actions_all(), 0)
        else:
            raise AssertionError(f"EmptyState has no check for the state {state!r}; checked: " + ", ".join(CHECKED_STATES))


@steps.step("Then I see the empty state {title}", level="e2e")
def then_i_see_the_empty_state_title(world, title):
    b = EmptyState(world.page, getattr(world, "base_url", ""))
    p.expect_text(b.heading(), str(title))


@steps.step("Then I see no empty state", level="e2e")
def then_i_see_no_empty_state(world):
    b = EmptyState(world.page, getattr(world, "base_url", ""))
    p.expect_count(b.box_all(), 0)


@steps.step("Then the empty state offers {name}", level="e2e")
def then_the_empty_state_offers_name(world, name):
    b = EmptyState(world.page, getattr(world, "base_url", ""))
    p.expect_visible(b.action(name))


@steps.step("When I take the empty state action {name}", level="e2e")
def when_i_take_the_empty_state_action_name(world, name):
    b = EmptyState(world.page, getattr(world, "base_url", ""))
    p.click(b.action(name))


@steps.step("Then the empty state is in the {state} state", level="e2e")
def then_the_empty_state_is_in_the_state_state(world, state):
    b = EmptyState(world.page, getattr(world, "base_url", ""))
    b.expect_state(state)
